// Generated by NextGuide CLI. Edit freely; NextGuide never overwrites these files.
import { Suspense } from "react"
import { notFound } from "next/navigation"
import { isMdxNotFound } from "nextguide/mdx"
import { DocsSitePage } from "nextguide/site"
import { docs, site, branding, editBase, getNeighbours } from "@/lib/nextguide"

export async function generateStaticParams() {
  const paths = await docs.getPagePaths()
  return paths.map((path) => ({ slug: path.split("/").filter(Boolean) }))
}

export async function generateMetadata({ params }: { params: Promise<{ slug?: string[] }> }) {
  const slug = ((await params).slug ?? []).join("/")
  // Browsers can probe /.well-known/* and other non-documentation paths.
  if (slug.startsWith(".well-known/") || slug.startsWith("_next/")) notFound()
  let frontmatter
  try {
    frontmatter = await docs.getFrontmatter({ slug })
  } catch (error) {
    if (isMdxNotFound(error)) notFound()
    throw error
  }
  const title = String(frontmatter.title ?? "Documentation")
  const description = String(frontmatter.description ?? site.description ?? "")
  const imagePath = "og/" + (slug || "index") + ".png"
  const imageUrl = "url" in site && typeof site.url === "string" && /^https?:\/\//.test(site.url)
    ? new URL(imagePath, site.url.replace(/\/?$/, "/")).toString()
    : "/" + imagePath
  const socialImage = branding.ogImage || imageUrl
  return {
    title, description,
    openGraph: { title, description, images: [{ url: socialImage, width: 1200, height: 630, alt: title }] },
    twitter: { card: "summary_large_image", images: [socialImage] },
  }
}

function DocumentationPending() {
  return (
    <div className="mx-auto max-w-[76rem] px-5 pt-10 pb-24 sm:px-10 lg:pt-14" role="status" aria-label="Loading documentation page">
      <span className="sr-only">Loading documentation page</span>
      <div className="max-w-3xl space-y-6 animate-pulse">
        <div className="h-4 w-40 rounded bg-muted" />
        <div className="h-9 w-3/5 rounded bg-muted" />
        <div className="h-4 w-full rounded bg-muted" />
        <div className="h-4 w-4/5 rounded bg-muted" />
        <div className="mt-10 h-36 rounded-lg bg-muted" />
      </div>
    </div>
  )
}

async function DocumentationBody({ params }: { params: Promise<{ slug?: string[] }> }) {
  const slug = ((await params).slug ?? []).join("/")
  if (slug.startsWith(".well-known/") || slug.startsWith("_next/")) notFound()
  const segments = slug ? slug.split("/") : []
  const breadcrumbs = [
    { title: "Documentation", href: "/" },
    ...segments.map((segment, i) => ({
      title: segment.replace(/[-_]/g, " "),
      ...(i < segments.length - 1 ? { href: "" + "/" + segments.slice(0, i + 1).join("/") } : {}),
    })),
  ]
  try {
    const { MDX, frontmatter, toc } = await docs.parse({ slug })
    if (segments.length) breadcrumbs[breadcrumbs.length - 1].title = String(frontmatter.title ?? "Documentation")
    const title = String(frontmatter.title ?? "Documentation")
    const neighbours = await getNeighbours(slug)
    return (
      <DocsSitePage title={title} description={frontmatter.description ? String(frontmatter.description) : undefined}
        toc={toc} markdown={await docs.read({ slug })} breadcrumbs={breadcrumbs}
        editUrl={editBase ? editBase + "/content/docs/" + (slug || "index") + ".mdx" : undefined}
        previous={neighbours.previous} next={neighbours.next}>
        {MDX}
      </DocsSitePage>
    )
  } catch (error) {
    if (isMdxNotFound(error)) notFound()
    throw error
  }
}

export default function DocumentationPage({ params }: { params: Promise<{ slug?: string[] }> }) {
  return (
    <Suspense fallback={<DocumentationPending />}>
      <DocumentationBody params={params} />
    </Suspense>
  )
}
